interface SubscriptionRow {
  email: string;
  user_id: string | null;
  tier: string | null;
  status: string | null;
  stripe_customer_id: string | null;
  stripe_subscription_id: string | null;
  current_period_end: string | null;
  cancel_at_period_end: boolean | null;
}

/** ⛔ ANYTHING THAT IS NOT A LIVE TIER READS AS null, INCLUDING THE RETIRED
 *  "team". Nobody ever bought it — the subscriptions table was empty when it was
 *  pulled, checked rather than assumed — so there is no row to migrate. If one
 *  ever appeared it would report a null tier against an active status, which the
 *  paywall shows as "no plan" rather than silently granting or silently
 *  downgrading. That is the right way round for a value we do not sell. */
function normaliseTier(raw: string | null | undefined): Tier | null {
  const v = String(raw ?? "").toLowerCase();
  return v === "pro" ? v : null;
}

function toEntitlement(row: SubscriptionRow | null): Entitlement {
  if (!row) return NO_ENTITLEMENT;
  const status = String(row.status ?? "none");
  return {
    active: ACTIVE_STATUSES.has(status),
    tier: normaliseTier(row.tier),
    status,
    pastDue: GRACE_STATUSES.has(status),
    email: row.email ?? null,
    stripeCustomerId: row.stripe_customer_id ?? null,
    currentPeriodEnd: row.current_period_end ?? null,
    cancelAtPeriodEnd: Boolean(row.cancel_at_period_end),
  };
}

/** Emails are compared lowercased everywhere, because Stripe echoes back what
 *  the buyer typed and Supabase stores what they typed at signup, and those are
 *  the same mailbox in different cases often enough to matter. */
export function normaliseEmail(email: string | null | undefined): string | null {
  const v = String(email ?? "").trim().toLowerCase();
  return v.length > 0 ? v : null;
}

/**
 * The account's subscription row, by user id first and email second.
 *
 * The email fallback is what makes a pay-first funnel work at all: between the
 * payment and the first sign-in the row has no user_id, so user_id alone would
 * report "never paid" to somebody who just did.
 */
export async function subscriptionFor(
  userId: string | null,
  email: string | null | undefined,
  sb: SupabaseClient = adminSupabase(),
): Promise<SubscriptionRow | null> {
  if (userId) {
    const { data, error } = await sb
      .from(SUBSCRIPTIONS_TABLE)
      .select("*")
      .eq("user_id", userId)
      .maybeSingle();
    if (error) throw error;
    if (data) return data as SubscriptionRow;
  }

  const addr = normaliseEmail(email);
  if (!addr) return null;
  const { data, error } = await sb
    .from(SUBSCRIPTIONS_TABLE)
    .select("*")
    .eq("email", addr)
    .maybeSingle();
  if (error) throw error;
  return (data as SubscriptionRow) ?? null;
}

/** The entitlement for a signed-in user. */
export async function entitlementFor(
  userId: string | null,
  email: string | null | undefined,
): Promise<Entitlement> {
  return toEntitlement(await subscriptionFor(userId, email));
}

/** Tier-gated capabilities ask this, never `tier === "<name>"` — a tier added
 *  above another would silently lose every capability it should inherit. */
export function tierAtLeast(ent: Entitlement, needed: Tier): boolean {
  if (!ent.active || !ent.tier) return false;
  return TIER_RANK[ent.tier] >= TIER_RANK[needed];
}

/**
 * Attach a payment made before the account existed, and seed the account.
 *
 * Called from the auth callback on every sign-in, not only the first: a buyer who
 * pays, signs in, and only then completes a second purchase still gets linked,
 * and re-running it on an already-linked account is a no-op.
 *
 * ⛔ IT ALSO WRITES THE SETTINGS ROW, AND THAT IS NOT A CONVENIENCE. Nothing in
 * this repo ever created one. `accountsToRun()` unions the accounts that HAVE a
 * settings row, so a fresh account was never walked by the overnight pass, and
 * `/api/webhooks/forms/[token]` validates the token by looking the account up in
 * leadgrade_settings — so a new account's own form endpoint answered 404 and
 * every lead posted to it was dropped. Both were silent.
 */
export async function linkSubscription(
  userId: string,
  email: string | null | undefined,
): Promise<Entitlement> {
  const sb = adminSupabase();
  const addr = normaliseEmail(email);

  if (addr) {
    // Claim the paid row for this account. Scoped to rows nobody has claimed, so
    // one person cannot take over another's subscription by changing their email.
    const { error } = await sb
      .from(SUBSCRIPTIONS_TABLE)
      .update({ user_id: userId, updated_at: new Date().toISOString() })
      .eq("email", addr)
      .is("user_id", null);
    if (error) throw error;
  }

  await seedAccount(userId);
  return toEntitlement(await subscriptionFor(userId, addr));
}

/**
 * The settings row every other part of this product assumes exists.
 *
 * Idempotent by construction: `ignoreDuplicates` on the account's own primary
 * key, so a second sign-in never resets a cap the buyer changed.
 */
export async function seedAccount(userId: string): Promise<void> {
  const sb = adminSupabase();
  const { error } = await sb.from("leadgrade_settings").upsert(
    {
      user_id: userId,
      autonomy: "copilot",
      autopilot_threshold: 70,
      daily_enrichment_cap: DEFAULT_DAILY_ENRICHMENT_CAP,
    },
    { onConflict: "user_id", ignoreDuplicates: true },
  );
  if (error) throw error;
}

/** True for the accounts the overnight pass and the dispatcher may work.
 *  Reads one row per account rather than one query per account. */
export async function activeAccountIds(candidates: string[]): Promise<Set<string>> {
  if (candidates.length === 0) return new Set();
  const { data, error } = await adminSupabase()
    .from(SUBSCRIPTIONS_TABLE)
    .select("user_id, status")
    .in("user_id", candidates);
  if (error) throw error;
  const out = new Set<string>();
  for (const row of (data ?? []) as { user_id: string | null; status: string | null }[]) {
    if (row.user_id && ACTIVE_STATUSES.has(String(row.status))) out.add(row.user_id);
  }
  return out;
}

/** The status a Stripe subscription object should be stored as. Exported so the
 *  webhook and this module cannot disagree about what "active" means. */
export function isActiveStatus(status: string | null | undefined): boolean {
  return ACTIVE_STATUSES.has(String(status ?? ""));
}

